"use client";

import { useId, useRef, useState, type CSSProperties, type KeyboardEvent, type PointerEvent } from "react";
import { useSkeuoTurnSound } from "./skeuo-sound-provider";
import { valueRange } from "./skeuo-value-range";
import "./styles/skeuo-rotary-knob.css";

export type SkeuoRotaryKnobProps = {
  label: string;
  value: number;
  onValueChange: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  disabled?: boolean;
  formatValue?: (value: number) => string;
};

const sweep = 270;
const ticks = Array.from({ length: 13 }, (_, index) => -sweep / 2 + index * sweep / 12);

function coordinates(event: PointerEvent<HTMLDivElement>) {
  const bounds = event.currentTarget.getBoundingClientRect();
  return { x: event.clientX - bounds.left - bounds.width / 2, y: event.clientY - bounds.top - bounds.height / 2 };
}

export function SkeuoRotaryKnob({
  label, value, onValueChange, min = 0, max = 100, step = 1,
  disabled = false, formatValue = String,
}: SkeuoRotaryKnobProps) {
  const id = useId();
  const playTick = useSkeuoTurnSound("knob");
  const range = valueRange(min, max, step);
  const current = range.clamp(value);
  const span = range.max - range.min;
  const unavailable = disabled || span <= 0;
  const [turning, setTurning] = useState(false);
  const drag = useRef<{ pointerId: number; angle: number | null; value: number; emitted: number } | null>(null);

  function startTurn(event: PointerEvent<HTMLDivElement>) {
    if (unavailable || !event.isPrimary || event.button !== 0) return;
    const { x, y } = coordinates(event);
    drag.current = {
      pointerId: event.pointerId,
      angle: Math.hypot(x, y) < 10 ? null : Math.atan2(y, x),
      value: current,
      emitted: current,
    };
    event.currentTarget.dataset.pointerFocus = "";
    event.currentTarget.focus({ preventScroll: true });
    event.currentTarget.setPointerCapture(event.pointerId);
    setTurning(true);
  }

  function turn(event: PointerEvent<HTMLDivElement>) {
    const gesture = drag.current;
    if (unavailable || !gesture || gesture.pointerId !== event.pointerId) return;
    const { x, y } = coordinates(event);
    if (Math.hypot(x, y) < 10) {
      gesture.angle = null;
      return;
    }
    const angle = Math.atan2(y, x);
    const previous = gesture.angle;
    gesture.angle = angle;
    if (previous === null) return;
    const delta = Math.atan2(Math.sin(angle - previous), Math.cos(angle - previous));
    gesture.value = range.clamp(gesture.value + delta * span / (sweep * Math.PI / 180));
    const next = range.nearest(gesture.value);
    if (next !== gesture.emitted) {
      const direction = next > gesture.emitted ? "clockwise" : "anticlockwise";
      gesture.emitted = next;
      onValueChange(next);
      playTick(direction);
    }
  }

  function endTurn(event: PointerEvent<HTMLDivElement>) {
    if (drag.current?.pointerId !== event.pointerId) return;
    drag.current = null;
    setTurning(false);
  }

  function handleKey(event: KeyboardEvent<HTMLDivElement>) {
    if (unavailable) return;
    const offsets: Record<string, number> = {
      ArrowUp: 1, ArrowRight: 1, ArrowDown: -1, ArrowLeft: -1, PageUp: 10, PageDown: -10,
    };
    const offset = Object.hasOwn(offsets, event.key) ? offsets[event.key] : 0;
    if (!offset && event.key !== "Home" && event.key !== "End") return;
    event.preventDefault();
    delete event.currentTarget.dataset.pointerFocus;
    const next = offset ? range.move(current, offset) : event.key === "Home" ? range.min : range.max;
    if (next !== current) {
      onValueChange(next);
      playTick(next > current ? "clockwise" : "anticlockwise");
    }
  }

  return (
    <div className="sk-rotary" data-sk-root="" data-disabled={unavailable || undefined}>
      <span className="sk-rotary-label" id={id}>{label}</span>
      <div className="sk-rotary-scale">
        <div className="sk-rotary-ticks" aria-hidden="true">
          {ticks.map((angle, index) => <i key={angle} data-major={index % 3 === 0 || undefined} style={{ "--sk-tick": `${angle}deg` } as CSSProperties} />)}
        </div>
        <span className="sk-rotary-min" aria-hidden="true">{range.min}</span>
        <span className="sk-rotary-max" aria-hidden="true">{range.max}</span>
        <div
          className="sk-rotary-control"
          role="slider"
          tabIndex={unavailable ? -1 : 0}
          aria-labelledby={id}
          aria-disabled={unavailable || undefined}
          aria-valuemin={range.min}
          aria-valuemax={range.max}
          aria-valuenow={current}
          aria-valuetext={formatValue(current)}
          data-turning={turning || undefined}
          onPointerDown={startTurn}
          onPointerMove={turn}
          onPointerUp={endTurn}
          onPointerCancel={endTurn}
          onLostPointerCapture={endTurn}
          onKeyDown={handleKey}
          onBlur={(event) => { delete event.currentTarget.dataset.pointerFocus; }}
        >
          <div className="sk-rotary-disc" aria-hidden="true" style={{ "--sk-angle": `${(span ? (current - range.min) / span : 0) * sweep - sweep / 2}deg` } as CSSProperties}>
            <div className="sk-rotary-face"><i /></div>
          </div>
        </div>
      </div>
      <span className="sk-rotary-readout" aria-hidden="true">{formatValue(current)}</span>
    </div>
  );
}

export function valueRange(min: number, max: number, step: number) {
  const lower = Number.isFinite(min) ? min : 0;
  const upper = Number.isFinite(max) && max >= lower ? max : lower;
  const increment = Number.isFinite(step) && step > 0 ? step : 1;

  function clamp(value: number) {
    return Number.isFinite(value) ? Math.min(upper, Math.max(lower, value)) : lower;
  }

  function atStep(index: number) {
    return clamp(Number((lower + index * increment).toPrecision(15)));
  }

  function nearest(value: number) {
    const bounded = clamp(value);
    return bounded === upper ? upper : atStep(Math.round((bounded - lower) / increment));
  }

  function move(value: number, steps: number) {
    const offset = (clamp(value) - lower) / increment;
    const index = Number(offset.toPrecision(15));
    return atStep(steps > 0 ? Math.floor(index) + steps : Math.ceil(index) + steps);
  }

  return { min: lower, max: upper, clamp, nearest, move };
}

"use client";
import { createContext, useContext, useEffect, useRef, type ReactNode } from "react";
export type SkeuoTurnDirection = "clockwise" | "anticlockwise";
export type SkeuoTurnSound = (direction: SkeuoTurnDirection, index: number) => void | Promise<void>;
const TurnSoundContext = createContext<{ enabled: boolean; onTurnSound?: SkeuoTurnSound; onKnobSound?: SkeuoTurnSound }>({ enabled: false });

/** A scoped detent event. Silent without an enabled provider and callback. */
export function useSkeuoTurnSound(control: "rim" | "knob" = "rim") {
  const { enabled, onTurnSound, onKnobSound } = useContext(TurnSoundContext);
  const play = control === "knob" ? onKnobSound ?? onTurnSound : onTurnSound;
  const lastTick = useRef(-Infinity);
  const index = useRef(0);
  return (direction: SkeuoTurnDirection) => {
    if (!enabled || !play) return;
    const now = performance.now();
    if (now - lastTick.current < 80) return;
    lastTick.current = now;
    try { void Promise.resolve(play(direction, index.current++)).catch(() => {}); }
    catch { /* Playback failures never prevent adjustment. */ }
  };
}

export type SkeuoSoundPhase = "down" | "up";
export type SkeuoSoundProviderProps = {
  children: ReactNode;
  enabled?: boolean;
  onTurnSound?: SkeuoTurnSound;
  onKnobSound?: SkeuoTurnSound;
  onSound?: (phase: SkeuoSoundPhase, index: number) => void;
};
/** Optional and silent by default. The host owns audio assets, playback, and preferences. */
export function SkeuoSoundProvider({ children, enabled = false, onSound, onTurnSound, onKnobSound }: SkeuoSoundProviderProps) {
  const counter = useRef(0);
  const down = useRef(new Map<number,number>());
  const recent = useRef(new WeakMap<Element,number>());
  const timers = useRef(new Set<ReturnType<typeof setTimeout>>());
  const current = useRef({enabled,onSound});
  useEffect(() => { current.current = {enabled,onSound}; }, [enabled,onSound]);
  useEffect(() => { const pending=timers.current; return () => {pending.forEach(clearTimeout);}; }, []);
  function play(phase: SkeuoSoundPhase, index: number) { if (current.current.enabled) { try {current.current.onSound?.(phase,index);} catch { /* Sound never prevents a control action. */ } } }
  function control(target: EventTarget | null) {
    if (!(target instanceof Element)) return null;
    const button=target.closest("button,[role='button'],a[data-sk-sound]");
    return button && !button.matches(":disabled,[aria-disabled='true'],[data-sound='off'],[data-sk-sound='off']") ? button : null;
  }
  return <TurnSoundContext.Provider value={{ enabled, onTurnSound, onKnobSound }}><div style={{display:"contents"}} onPointerDownCapture={event => {
    const button=control(event.target);
    if(!enabled || !button || !event.isPrimary || event.button !== 0 || event.pointerType === "touch") return;
    const index=counter.current++;down.current.set(event.pointerId,index);recent.current.set(button,performance.now());play("down",index);
  }} onPointerUpCapture={event => {
    const index=down.current.get(event.pointerId);if(index === undefined) return;
    down.current.delete(event.pointerId);const button=control(event.target);if(button)recent.current.set(button,performance.now());play("up",index);
  }} onPointerCancelCapture={event => {const index=down.current.get(event.pointerId);if(index !== undefined){down.current.delete(event.pointerId);play("up",index);}}} onClickCapture={event => {
    const button=control(event.target);
    if(!enabled || !button || performance.now()-(recent.current.get(button) ?? -Infinity)<600) return;
    const index=counter.current++;play("down",index);
    const timer=setTimeout(() => {timers.current.delete(timer);play("up",index);},45);timers.current.add(timer);
  }}>{children}</div></TurnSoundContext.Provider>;
}

@import "./skeuo-base.css";

:where(:root, .light, [data-theme="light"]) {
  --sk-rotary-finish: #d2c8b5;
  --sk-rotary-rim: #8d826f;
  --sk-rotary-index: #335d49;
}
:where(.dark, [data-theme="dark"]) {
  --sk-rotary-finish: #89978e;
  --sk-rotary-rim: #4d6055;
  --sk-rotary-index: #d1e8bb;
}
@media (prefers-color-scheme: dark) {
  :where(html:not(.light):not(.dark):not([data-theme])) {
    --sk-rotary-finish: #89978e;
    --sk-rotary-rim: #4d6055;
    --sk-rotary-index: #d1e8bb;
  }
}

.sk-rotary {
  --sk-rotary-body: color-mix(in srgb, var(--sk-surface) 91%, #c8a575);
  --sk-rotary-lip: color-mix(in srgb, var(--sk-base) 84%, #aa8d66);
  display: grid;
  justify-items: center;
  gap: 18px;
  width: min(100%, 358px);
  padding: 24px clamp(12px, 5vw, 26px) 22px;
  border: 1px solid var(--sk-rotary-lip);
  border-radius: 20px;
  background: linear-gradient(150deg, var(--sk-surface-raised), var(--sk-rotary-body));
  color: var(--sk-card-ink);
  box-shadow: inset 0 2px var(--sk-highlight), inset 0 -3px var(--sk-rotary-lip),
    0 4px var(--sk-base), 0 5px var(--sk-edge), 0 8px 12px #0002;
}

.sk-rotary-label { font-size: 22px; font-weight: 650; overflow-wrap: anywhere; }
.sk-rotary-scale { width: min(100%, 252px); aspect-ratio: 1; position: relative; }
.sk-rotary-ticks { position: absolute; inset: 0; overflow: clip; pointer-events: none; }
.sk-rotary-ticks i { position: absolute; inset: 0; transform: rotate(var(--sk-tick)); }
.sk-rotary-ticks i::before {
  content: "";
  position: absolute;
  top: 3%;
  left: calc(50% - 1.5px);
  width: 3px;
  height: 4%;
  border-radius: 3px;
  background: color-mix(in srgb, var(--sk-muted) 80%, black);
  box-shadow: inset 0 2px 2px #0007, 0 1px var(--sk-highlight);
}
.sk-rotary-ticks i[data-major]::before { height: 5.75%; }
.sk-rotary-min, .sk-rotary-max {
  position: absolute;
  bottom: 8%;
  color: var(--sk-muted);
  font: 11px var(--sk-font-mono);
  font-variant-numeric: tabular-nums;
}
.sk-rotary-min { left: 8%; }
.sk-rotary-max { right: 8%; }

.sk-rotary-control {
  position: absolute;
  inset: 12%;
  padding: 5px;
  border: 1px solid var(--sk-rotary-lip);
  border-radius: 50%;
  background: linear-gradient(155deg, var(--sk-surface-raised), var(--sk-rotary-lip) 76%);
  box-shadow: inset 0 1px var(--sk-highlight), inset 0 -1px 2px #0002,
    0 2px var(--sk-rotary-lip), 0 5px 9px -2px #1b18152b;
  cursor: grab;
  touch-action: none;
  user-select: none;
}
.sk-rotary-control::before {
  content: "";
  position: absolute;
  inset: 5px;
  border-radius: inherit;
  box-shadow: 0 2px 2px #16141032, 0 4px 6px -2px #16141028;
  pointer-events: none;
}
.sk-rotary-control[data-turning] { cursor: grabbing; }
.sk-rotary-control:focus-visible { outline: 2px solid var(--sk-ring); outline-offset: 5px; }
.sk-rotary-control[data-pointer-focus]:focus { outline: none; }
.sk-rotary-disc {
  position: relative;
  width: 100%;
  height: 100%;
  padding: clamp(8px, 2vw, 11px);
  border: 1px solid color-mix(in srgb, var(--sk-rotary-rim) 65%, black);
  border-radius: inherit;
  transform: rotate(var(--sk-angle));
  background: repeating-conic-gradient(
    color-mix(in srgb, var(--sk-rotary-rim) 55%, black) 0deg 1.8deg,
    color-mix(in srgb, var(--sk-rotary-rim) 77%, white) 2.3deg 5.1deg,
    var(--sk-rotary-rim) 5.9deg 7.5deg
  );
  box-shadow: inset 0 0 2px #ffffff58;
}
@media (prefers-reduced-motion: no-preference) {
  .sk-rotary-disc { transition: transform 95ms ease-out; }
}
.sk-rotary-disc::before {
  content: "";
  position: absolute;
  inset: 5px;
  border: 1px solid color-mix(in srgb, var(--sk-rotary-rim) 63%, black);
  border-radius: inherit;
  background: linear-gradient(165deg,
    color-mix(in srgb, var(--sk-rotary-rim) 50%, black),
    var(--sk-rotary-rim) 48%,
    color-mix(in srgb, var(--sk-rotary-finish) 72%, white));
  box-shadow: inset 0 3px 4px #17130f82, 0 1px #ffffff59;
  pointer-events: none;
}
.sk-rotary-face {
  position: relative;
  width: 100%;
  height: 100%;
  border: 1px solid color-mix(in srgb, var(--sk-rotary-rim) 72%, black);
  border-radius: inherit;
  background: repeating-linear-gradient(0deg, #ffffff12 0 1px, transparent 1px 3px),
    linear-gradient(140deg, color-mix(in srgb, var(--sk-rotary-finish) 60%, white), var(--sk-rotary-finish) 47%, var(--sk-rotary-rim));
  box-shadow: inset 0 4px 6px #15120e60, inset 3px 0 5px #15120e42,
    inset -2px 0 4px #15120e30, inset 0 -2px 2px #ffffff75, 0 1px #ffffff3d;
}
.sk-rotary-face i {
  position: absolute;
  top: 9%;
  left: calc(50% - 2.5px);
  width: 5px;
  height: 32%;
  border-radius: 4px;
  background: var(--sk-rotary-index);
  box-shadow: inset 0 1px #ffffff55, 0 1px 3px #0006;
}
.sk-rotary-readout {
  min-width: 96px;
  max-width: 100%;
  padding: 6px 13px;
  text-align: center;
  overflow-wrap: anywhere;
  border: 1px solid var(--sk-edge);
  border-radius: 7px;
  background: var(--sk-well);
  box-shadow: inset 0 4px 6px #0003, inset 1px 1px 3px #0002, 0 2px var(--sk-highlight);
  font: 600 17px var(--sk-font-mono);
  font-variant-numeric: tabular-nums;
}
.sk-rotary[data-disabled] { opacity: .55; }
.sk-rotary[data-disabled] .sk-rotary-control { cursor: not-allowed; touch-action: auto; }

@import "./skeuo-tokens.css";
:where([data-sk-root],[data-sk-root] *) {box-sizing:border-box;}
:where([data-sk-root]) {font-family:var(--sk-font-sans,system-ui,sans-serif);font-size:14px;line-height:1.5;color:var(--sk-ink);}
:where([data-sk-root] button,[data-sk-root] input,[data-sk-root] textarea) {font:inherit;}
:where([data-sk-root] :is(h1,h2,h3,h4,p,figure,blockquote,ul)) {margin:0;}
:where([data-sk-root] button) {cursor:pointer;}
:where([data-sk-root]:focus-visible,[data-sk-root] :focus-visible) {outline:2px solid var(--sk-ring);outline-offset:3px;}
:where([data-sk-root] button:disabled) {cursor:not-allowed;}

/* Exact material defaults, with optional host semantic colors. Public host tokens are never written. */
:where(:root,.light,[data-theme="light"]) {
  --sk-album-paper: var(--card, #faf9f5);--sk-album-ink: var(--card-foreground, #45423b);--sk-album-edge: var(--border, #c4c2ba);--sk-album-base: var(--sk-sem-album-base, #d6d4ca);
  --sk-bg: var(--background, #fff); --sk-ink: var(--foreground, #202020); --sk-muted: var(--muted-foreground, #686863); --sk-line: var(--border, #e7e7e4);
  --sk-surface: var(--card, #f5f5f2); --sk-surface-raised: var(--sk-sem-surface-raised, #fafaf8); --sk-well: var(--muted, #e9e9e5);
  --sk-edge: var(--border, #d1d1cb); --sk-highlight: #fff; --sk-base: var(--sk-sem-base, #d9d9d3); --sk-shadow: #00000017;
  --sk-field-shadow: inset 0 3px 6px var(--sk-shadow),inset 1px 1px 2px var(--sk-shadow),0 1px 0 var(--sk-highlight);
  --sk-accent: var(--primary, #365e50); --sk-accent-bright: var(--sk-sem-accent-bright, #487b68); --sk-accent-base: var(--sk-sem-accent-base, #213c32); --sk-accent-edge: var(--sk-sem-accent-edge, #294b3e); --sk-accent-ink: var(--primary-foreground, #fff);
  --sk-key: var(--secondary, #f9f9f7); --sk-key-edge: var(--border, #c6c7c1); --sk-key-base: var(--sk-sem-key-base, #d0d1ca);
  --sk-font-mono: ui-monospace, SFMono-Regular, Consolas, monospace; --sk-font-sans: system-ui, sans-serif;

}
:where(.dark,[data-theme="dark"]) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
  --sk-accent: var(--primary, #9ab5a6); --sk-accent-bright: var(--sk-sem-accent-bright, #bbcec2); --sk-accent-base: var(--sk-sem-accent-base, #4d6558); --sk-accent-edge: var(--sk-sem-accent-edge, #6f8a79); --sk-accent-ink: var(--primary-foreground, #14251c);
  --sk-key: var(--secondary, #292a29); --sk-key-edge: var(--border, #484946); --sk-key-base: var(--sk-sem-key-base, #101110);

}
@media(prefers-color-scheme:dark) { :where(html:not(.light):not(.dark):not([data-theme])) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
  --sk-accent: var(--primary, #9ab5a6); --sk-accent-bright: var(--sk-sem-accent-bright, #bbcec2); --sk-accent-base: var(--sk-sem-accent-base, #4d6558); --sk-accent-edge: var(--sk-sem-accent-edge, #6f8a79); --sk-accent-ink: var(--primary-foreground, #14251c);
  --sk-key: var(--secondary, #292a29); --sk-key-edge: var(--border, #484946); --sk-key-base: var(--sk-sem-key-base, #101110);

} }

:where(:root,.light,.dark,[data-theme="light"],[data-theme="dark"]) {
  --sk-sem-accent-bright: color-mix(in srgb,var(--primary) 84%,white);
  --sk-sem-accent-base: color-mix(in srgb,var(--primary) 65%,black);
  --sk-sem-accent-edge: color-mix(in srgb,var(--primary) 78%,black);
  --sk-sem-base: color-mix(in srgb,var(--card) 85%,black);
  --sk-sem-surface-raised: color-mix(in srgb,var(--card) 96%,white);
  --sk-sem-key-base: color-mix(in srgb,var(--secondary) 83%,black);
  --sk-sem-album-base: color-mix(in srgb,var(--card) 83%,black);
  --sk-card-ink: var(--card-foreground,var(--sk-ink));
  --sk-sem-secondary-raised: color-mix(in srgb,var(--secondary) 96%,white);
  --sk-sem-secondary-base: color-mix(in srgb,var(--secondary) 83%,black);
  --sk-secondary: var(--secondary,var(--sk-surface));
  --sk-secondary-ink: var(--secondary-foreground,var(--sk-ink));
  --sk-secondary-raised: var(--sk-sem-secondary-raised,var(--sk-surface-raised));
  --sk-secondary-base: var(--sk-sem-secondary-base,var(--sk-base));
  --sk-input-edge: var(--input,var(--sk-edge));
  --sk-ring: var(--ring,var(--sk-accent));
}
